/** Isolated A/B oracle runner. No agent answers are generated by this script.
 * node --import tsx scripts/bench-bench.ts TASK HUB_A HUB_B [PORT] --root NEW_DIR
 * Seats may connect externally to the isolated hubs; only workspace/ is seat-visible.
 * Filesystem hiding is NOT a sandbox: run untrusted seats in a separate restricted container.
 */
import { spawn, execFileSync, type ChildProcess } from 'node:child_process';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync, readdirSync, lstatSync, cpSync, openSync, closeSync, realpathSync } from 'node:fs';
import { resolve, join, dirname, relative } from 'node:path';
import { createServer } from 'node:net';
import { pathToFileURL, fileURLToPath } from 'node:url';
const delay=(ms:number)=>new Promise(r=>setTimeout(r,ms));
const json=(path:string,value:unknown)=>writeFileSync(path,JSON.stringify(value,null,2)+'\n');
function hashTree(path:string):string {
 const hash=createHash('sha256');
 const visit=(p:string)=>{const st=lstatSync(p);if(st.isSymbolicLink())throw Error(`Symlink not permitted: ${p}`);
  if(st.isDirectory())for(const name of readdirSync(p).sort())visit(join(p,name));
  else if(st.isFile()){hash.update(relative(path,p));hash.update('\0');hash.update(readFileSync(p));hash.update('\0');}
 };
 visit(path);return hash.digest('hex');
}
function hashFile(path:string){return existsSync(path)?createHash('sha256').update(readFileSync(path)).digest('hex'):null;}
function revision(entry:string):string|null {
 try{return execFileSync('git',['-C',dirname(entry),'rev-parse','HEAD'],{encoding:'utf8',stdio:['ignore','pipe','ignore']}).trim();}catch{return null;}
}
async function stop(child:ChildProcess) {
 if(child.exitCode!==null||child.signalCode!==null||!child.pid)return;
 child.kill('SIGTERM');
 await Promise.race([new Promise<void>(ok=>child.once('exit',()=>ok())),delay(500)]);
 if(child.exitCode===null&&child.signalCode===null){child.kill('SIGKILL');await Promise.race([new Promise<void>(ok=>child.once('exit',()=>ok())),delay(500)]);}
}
function conclusions(log:string):boolean {
 if(!existsSync(log))return false;
 // Ignore only an unfinished trailing record, never silently accept corrupt complete records.
 const lines=readFileSync(log,'utf8').split('\n');lines.pop();
 return lines.filter(Boolean).map(line=>JSON.parse(line)).some(e=>e.type==='state'&&e.state==='concluded'&&typeof e.conclusion?.text==='string');
}
async function main() {
 const argv=process.argv.slice(2);const taskArg=argv.shift(),aArg=argv.shift(),bArg=argv.shift();
 if(!taskArg||!aArg||!bArg)throw Error('Usage: bench-bench.ts TASK HUB_A HUB_B [PORT] --root NEW_DIR [--timeout-ms N]');
 const port=Number(argv[0]&&!argv[0].startsWith('--')?argv.shift():18850);
 if(!Number.isInteger(port)||port<=8000||port>65534)throw Error('Invalid port: use integer port >8000 and <=65534 (two adjacent ports)');
 let rootArg:string|undefined;let timeout=60000;let seatArg:string|undefined;
 while(argv.length){const option=argv.shift();if(option==='--root')rootArg=argv.shift();else if(option==='--timeout-ms')timeout=Number(argv.shift());else if(option==='--seat-entry')seatArg=resolve(argv.shift()!);else throw Error(`Unknown option ${option}`);}
 if(!Number.isFinite(timeout)||timeout<1)throw Error('Invalid timeout');
 if(seatArg&&!existsSync(seatArg))throw Error(`Seat entry not found: ${seatArg}`);
 const root=resolve(rootArg??`/tmp/bench-${Date.now()}-${process.pid}`);
 if(existsSync(root))throw Error(`Refusing to reuse ${root}`);
 // Check both ports before creating output. Closing the probes is necessarily racy; boot failure is infra.
 for(const p of [port,port+1]){const probe=createServer();await new Promise<void>((ok,no)=>{probe.once('error',no);probe.listen(p,'127.0.0.1',()=>probe.close(()=>ok()));});}
 const taskDir=realpathSync(resolve(taskArg));
 const scorerPath=resolve(dirname(fileURLToPath(import.meta.url)),'bench-oracle.ts');
 const factScorerPath=resolve(dirname(scorerPath),'score-fact-check.ts');
 const factScorerBefore=hashFile(factScorerPath);
 const scorer=await import(pathToFileURL(scorerPath).href);
 const task=scorer.loadTask(taskDir);
 const taskBefore=hashTree(taskDir);const scorerBefore=hashFile(scorerPath);
 const providerEntry=resolve(process.env.BENCH_SEAT_ENTRY??resolve(dirname(scorerPath),'../dist/openrouter.js'));
 const frozen={seat_entry_sha256:seatArg?hashFile(seatArg):null,provider_entry_sha256:seatArg?hashFile(providerEntry):null,expected_participants:seatArg?1:0,task_sha256:taskBefore,scorer_sha256:scorerBefore,fact_scorer_sha256:factScorerBefore,task_id:task.task_id,timeout_ms:timeout,room:'benchmark',brief:readFileSync(join(taskDir,'public','brief.txt'),'utf8')};
 mkdirSync(root);const results:any[]=[];
 for(const [index,entryArg] of [aArg,bArg].entries()) {
  const arm=index===0?'A':'B',armRoot=join(root,arm),workspace=join(armRoot,'workspace');
  mkdirSync(armRoot);mkdirSync(join(armRoot,'data'));
  const entry=resolve(entryArg);const started=Date.now();let child:ChildProcess|undefined;let fd:number|undefined;
  const manifest:any={arm,port:port+index,root:armRoot,workspace,seat_entry:seatArg??null,seat_pid:null,seat_exit_code:undefined,hub_entry:entry,hub_revision:revision(entry),hub_entry_sha256:hashFile(entry),hub_build_sha256:null,hub_version:null,provenance_scope:dirname(entry).endsWith('/dist')?'dist-tree; external dependencies not covered':'entry-only; imported modules not covered',frozen,started_at:new Date().toISOString()};
  // Hash the selected build's directory, not launcher HEAD. Non-dist stubs are hashed by entry.
  if(existsSync(entry))manifest.hub_build_sha256=dirname(entry).endsWith('/dist')?hashTree(dirname(entry)):manifest.hub_entry_sha256;
  let seat:ChildProcess|undefined;
  const verdict:any={task_id:task.task_id,arm,hub_entry:entry,hub_revision:manifest.hub_revision,passed:false,reason:'infrastructure_error',oracle:{kind:task.oracle.kind,command:null,exit_code:null},anti_tamper:{hash_before:taskBefore,hash_after:null,unchanged:false},diagnostics:{reply_metrics_path:null,mentions:null,reply_rate:null},duration_ms:0,checked_at:null};
  const save=()=>json(join(armRoot,'manifest.json'),manifest);save();
  try {
   if(hashTree(taskDir)!==taskBefore||hashFile(scorerPath)!==scorerBefore||hashFile(factScorerPath)!==factScorerBefore){verdict.reason='tamper';throw Error('Frozen task or scorer changed');}
   cpSync(join(taskDir,'public'),workspace,{recursive:true,errorOnExist:true,force:false});
   const env={...process.env};for(const key of Object.keys(env))if(key.startsWith('CHATROOM_')||/API_KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL/i.test(key))delete env[key];
   Object.assign(env,{PORT:String(port+index),HOST:'127.0.0.1',CHATROOM_DATA_DIR:join(armRoot,'data'),CHATROOM_DEFAULT_CWD:workspace,CHATROOM_LOG_DIR:join(armRoot,'spawned')});
   fd=openSync(join(armRoot,'hub.log'),'w');child=spawn(process.execPath,[entry],{cwd:workspace,env,stdio:['ignore',fd,fd]});
   manifest.hub_pid=child.pid;let spawnError:Error|undefined;child.on('error',error=>{spawnError=error;});
   const url=`http://127.0.0.1:${port+index}`;let ready=false;
   while(Date.now()-started<timeout){if(spawnError)throw spawnError;if(child.exitCode!==null)throw Error(`Hub exited ${child.exitCode}`);
    try{const response=await fetch(`${url}/rooms`,{signal:AbortSignal.timeout(Math.min(timeout,500))});if(response.ok){ready=true;const value=await response.json();manifest.hub_version=value.version??null;break;}}catch{}
    await delay(30);
   }
   if(!ready)throw Error('Hub did not become ready');manifest.booted_at=new Date().toISOString();save();
 const created=await fetch(`${url}/rooms/benchmark/create`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:frozen.brief,expected_participants:frozen.expected_participants,quorum:'unanimous',require_challenge:!seatArg,require_verification:false}),signal:AbortSignal.timeout(timeout)});
   if(!created.ok)throw Error(`Room create HTTP ${created.status}`);
   let seatError:Error|undefined;
   if(seatArg){
    // Hub credentials stay scrubbed; allow only this provider's credentials into the seat.
    const seatEnv={...env,CHATROOM_MCP_URL:`${url}/mcp`,BENCH_SEAT_ENTRY:providerEntry,BENCH_HUB_ENTRY:entry};
    for(const key of ['OPENROUTER_API_KEY','OPENROUTER_BASE_URL','OPENROUTER_MODEL'])if(process.env[key])Object.assign(seatEnv,{[key]:process.env[key]});
    seat=spawn(process.execPath,[seatArg],{cwd:workspace,env:seatEnv,stdio:['ignore',fd,fd]});manifest.seat_pid=seat.pid;
    seat.on('error',error=>{seatError=error;});
    seat.on('exit',(code,signal)=>{manifest.seat_exit_code=code;manifest.seat_exit_signal=signal;manifest.seat_completed_at=new Date().toISOString();save();});save();
   }
   const checkSeat=()=>{if(seatError)throw seatError;if(seat&&(seat.signalCode!==null||(seat.exitCode!==null&&seat.exitCode!==0)))throw Error(`Seat failed: ${seat.exitCode??seat.signalCode}`);};
   while(!conclusions(join(armRoot,'data','benchmark.jsonl'))){checkSeat();if(child.exitCode!==null||spawnError)throw Error('Hub exited before conclusion');if(Date.now()-started>=timeout){verdict.reason='timeout';throw Error('Conclusion timeout');}await delay(30);}
   // Conclusion precedes wrapper artifact writes. Keep the hub alive until the seat exits.
   while(seat&&seat.exitCode===null&&seat.signalCode===null){checkSeat();if(Date.now()-started>=timeout){verdict.reason='timeout';throw Error('Seat completion timeout');}await delay(30);}
   checkSeat();
   await stop(child);
   manifest.scoring_started_at=new Date().toISOString();
   if(hashTree(taskDir)!==taskBefore||hashFile(scorerPath)!==scorerBefore||hashFile(factScorerPath)!==factScorerBefore){verdict.reason='tamper';throw Error('Frozen task or scorer changed');}
   Object.assign(verdict,await scorer.scoreTask(taskDir,workspace));
  }catch(error){manifest.error=String(error);}
  finally {
   if(seat)await stop(seat);if(child)await stop(child);if(fd!==undefined)closeSync(fd);
   let after:string|null=null;try{after=hashTree(taskDir);}catch{}
   const unchanged=after===taskBefore&&hashFile(scorerPath)===scorerBefore&&hashFile(factScorerPath)===factScorerBefore;
   verdict.anti_tamper={...verdict.anti_tamper,hash_before:taskBefore,hash_after:after,unchanged};
   if(!unchanged){verdict.passed=false;verdict.reason='tamper';}
   verdict.duration_ms=Date.now()-started;verdict.checked_at=new Date().toISOString();
   manifest.stopped_at=verdict.checked_at;save();json(join(armRoot,'bench-result.json'),verdict);results.push(verdict);
  }
 }
 const comparable=results.every(v=>!['infrastructure_error','timeout','tamper'].includes(v.reason));
 json(join(root,'bench-compare.json'),{task_id:task.task_id,arms:results.map(v=>({arm:v.arm,passed:v.passed,reason:v.reason})),comparable,delta:comparable?Number(results[1].passed)-Number(results[0].passed):null,delta_unit:'success indicator B minus A; single trial, not an effect estimate',frozen,checked_at:new Date().toISOString()});
 console.log(root);
}
main().catch(error=>{console.error(String(error));process.exitCode=1;});
